+                 */
+                return initialAllowedBytes - allowedBytes;
+            }
+
+            @Override
+            public long getLimit() {
+                /*
+                 * This isn't expected to be used by we can implement it so we may as
+                 * well. Maybe it'll be useful for debugging one day.
+                 */
+                return initialAllowedBytes;
+            }
